/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  Sequence,
  spring,
  useCurrentFrame,
  useVideoConfig,
  random,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

// Load bold, condensed font for athletic performance feel
const { fontFamily: oswaldFamily } = loadOswald();



export type KineticOverlayProps = Record<string, any>;

const KineticOverlay: React.FC<KineticOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 15, // Increased default to 15s for smoother reading times
  accentColor = "#A2F50B", // VRTX Green
  textColor = "#FFFFFF",
  hookLine1 = "NO SLIP",
  hookLine2 = "NO WASTED MOVEMENT",
  syncText = "LOCKED IN",
  syncSubLines = ["ZERO LATENCY", "MAXIMUM YIELD", "ABSOLUTE PRECISION"],
  stackWords = ["GRIP", "CONTROL", "POWER"],
  advantageLine1 = "THE DIFFERENCE",
  advantageLine2 = "IS CONTROL",
  logoImage = "https://images.unsplash.com/photo-1614680376573-df3480f0c6ff?q=80&w=400&auto=format&fit=crop",
  finalLine2 = "NOTHING MOVES",
  ctaText = "SHOP NOW",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- RESPONSIVE TIMING CALCULATIONS ---
  // Reserve exactly 3 seconds for the final CTA hold
  const finalHoldFrames = fps * 3;
  const introFrames = Math.max(durationInFrames - finalHoldFrames, fps * 2); // Ensure intro is at least 2s

  // Map the previous percentages proportionally to the intro duration
  const p20 = Math.floor(introFrames * 0.25);
  const p25 = Math.floor(introFrames * 0.3125);
  const p40 = Math.floor(introFrames * 0.50);
  const p45 = Math.floor(introFrames * 0.5625);
  const p60 = Math.floor(introFrames * 0.75);
  const p65 = Math.floor(introFrames * 0.8125);
  
  // Start Scene 5 with exactly the remaining 3 seconds
  const p80 = introFrames;
  const p85 = introFrames + Math.floor(fps * 0.5); // 0.5s fade in for scene 5
  const p95 = durationInFrames - Math.floor(fps * 0.5); // 0.5s global fade out at the very end

  // --- SCENE 1: HARD HOOK (0 to p25) ---
  const s1Opacity = interpolate(frame, [p20, p25], [1, 0], { extrapolateRight: "clamp" });
  
  const s1Slam1 = spring({
    frame,
    fps,
    config: { damping: 18, stiffness: 120, mass: 0.8 }, // Smoother settlement
  });
  const s1X1 = interpolate(s1Slam1, [0, 1], [-width, width * 0.1]);
  const s1Blur1 = interpolate(s1Slam1, [0, 0.8, 1], [40, 5, 0]);

  const s1Delay2 = 10;
  const s1Slam2 = spring({
    frame: frame - s1Delay2,
    fps,
    config: { damping: 18, stiffness: 120, mass: 0.8 },
  });
  const s1X2 = interpolate(s1Slam2, [0, 1], [-width, width * 0.1]);
  const s1Blur2 = interpolate(s1Slam2, [0, 0.8, 1], [40, 5, 0]);

  const shakeX =
    frame > 15 && frame < 35
      ? interpolate(frame, [15, 20, 25, 30, 35], [0, -3, 3, -1, 0])
      : 0;

  // --- SCENE 2: MOVEMENT SYNC (p20 to p45) ---
  const s2LocalFrame = frame - p20;
  const s2Opacity = interpolate(frame, [p20, p25, p40, p45], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const s2TextIn = spring({
    frame: s2LocalFrame - 10, // Wait for crossfade to start
    fps,
    config: { damping: 18, stiffness: 100 },
  });
  const s2X = interpolate(s2TextIn, [0, 1], [200, 0]);
  const s2Blur = interpolate(s2TextIn, [0, 1], [20, 0]);
  
  const s2LineScale = spring({
    frame: s2LocalFrame - 15,
    fps,
    config: { damping: 20, stiffness: 120 },
  });

  const s2BgTextX = interpolate(s2LocalFrame, [0, p45 - p20], [width, -width * 2], {
    extrapolateRight: "clamp",
  });

  // --- SCENE 3: PERFORMANCE STACK (p40 to p65) ---
  const s3LocalFrame = frame - p40;
  const s3Opacity = interpolate(frame, [p40, p45, p60, p65], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const s3TotalDuration = p65 - p40;
  const timePerWord = Math.floor(s3TotalDuration / Math.max(1, stackWords.length));
  const currentWordIndex = Math.min(
    Math.floor(s3LocalFrame / timePerWord),
    stackWords.length - 1
  );
  const wordLocalFrame = s3LocalFrame % timePerWord;

  const s3WordY = interpolate(wordLocalFrame, [0, timePerWord], [40, -10], {
    extrapolateRight: "clamp",
  });
  const s3WordOpacity = interpolate(
    wordLocalFrame,
    [0, 10, timePerWord - 10, timePerWord],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const s3FlashOpacity = interpolate(wordLocalFrame, [0, 8, 20], [0.15, 0, 0], {
    extrapolateRight: "clamp",
  });

  // --- SCENE 4: ADVANTAGE FRAME (p60 to p85) ---
  const s4LocalFrame = frame - p60;
  const s4Opacity = interpolate(frame, [p60, p65, p80, p85], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const s4BgOpacity = interpolate(s4LocalFrame, [10, 30], [0, 0.6], { extrapolateRight: "clamp" });

  const s4Text1In = spring({
    frame: s4LocalFrame - 5,
    fps,
    config: { damping: 18, stiffness: 100 },
  });
  const s4Y1 = interpolate(s4Text1In, [0, 1], [100, 0]);

  const s4Text2In = spring({
    frame: s4LocalFrame - 15,
    fps,
    config: { damping: 18, stiffness: 100 },
  });
  const s4Y2 = interpolate(s4Text2In, [0, 1], [100, 0]);

  const s4LineScale = spring({
    frame: s4LocalFrame - 20,
    fps,
    config: { damping: 20, stiffness: 100 },
  });

  // --- SCENE 5: FINAL HIT (p80 to End) ---
  const s5LocalFrame = frame - p80;
  const s5Opacity = interpolate(frame, [p80, p85], [0, 1], { extrapolateRight: "clamp" });

  const s5ScaleIn = interpolate(s5LocalFrame, [0, durationInFrames - p80], [0.85, 1], {
    extrapolateRight: "clamp",
  });

  const s5Glow = interpolate(s5LocalFrame, [20, 40, 60], [0, 30, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  
  const s5CtaScale = spring({
    frame: s5LocalFrame - 15,
    fps,
    config: { damping: 15, stiffness: 200 },
  });

  const globalFadeOut = interpolate(frame, [p95, durationInFrames], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: oswaldFamily,
        color: textColor,
        opacity: globalFadeOut,
      }}
    >
      {/* Global Performance Dark Gradient Overlay */}
      <AbsoluteFill
        style={{
          background: "linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.7) 100%)",
          pointerEvents: "none",
        }}
      />

      {/* --- SCENE 1: HARD HOOK --- */}
      <Sequence from={0} durationInFrames={p25}>
        <AbsoluteFill style={{ opacity: s1Opacity, justifyContent: "center", transform: `translateX(${shakeX}px)` }}>
          <div style={{ transform: `translateX(${s1X1}px)`, filter: `blur(${s1Blur1}px)`, marginBottom: "20px" }}>
            <h1
              style={{
                fontSize: width * 0.18,
                margin: 0,
                lineHeight: 1,
                textTransform: "uppercase",
                fontStyle: "italic", // Adds to kinetic feel
                textShadow: "4px 4px 0px rgba(0,0,0,0.5)",
              }}
            >
              {hookLine1}
            </h1>
          </div>
          <div style={{ transform: `translateX(${s1X2}px)`, filter: `blur(${s1Blur2}px)` }}>
            <h2
              style={{
                fontSize: width * 0.09,
                margin: 0,
                color: accentColor,
                lineHeight: 1,
                textTransform: "uppercase",
                textShadow: "3px 3px 0px rgba(0,0,0,0.5)",
              }}
            >
              {hookLine2}
            </h2>
          </div>
        </AbsoluteFill>
      </Sequence>

      {/* --- SCENE 2: MOVEMENT SYNC --- */}
      <Sequence from={p20} durationInFrames={p45 - p20}>
        <AbsoluteFill style={{ opacity: s2Opacity }}>
          {/* Massive Background Scrolling Text to keep dynamic attention */}
          <AbsoluteFill style={{ justifyContent: "center", alignItems: "center", opacity: 0.15 }}>
            <h1
              style={{
                position: "absolute",
                fontSize: width * 0.5,
                color: "transparent",
                WebkitTextStroke: `3px ${textColor}`,
                whiteSpace: "nowrap",
                transform: `translateX(${s2BgTextX}px)`,
                margin: 0,
                fontStyle: "italic",
              }}
            >
              {syncText} {syncText} {syncText}
            </h1>
          </AbsoluteFill>

          {/* Horizontal Directional Streaks */}
          {Array.from({ length: 6 }).map((_, i) => {
            const startDelay = random(`s-${i}`) * 30;
            const streakY = random(`y-${i}`) * height;
            const streakSpeed = interpolate(
              s2LocalFrame - startDelay,
              [0, 30],
              [-width, width * 1.5],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  top: streakY,
                  left: streakSpeed,
                  width: width * 0.4,
                  height: i % 2 === 0 ? 4 : 8,
                  backgroundColor: i % 3 === 0 ? accentColor : "#FFFFFF",
                  opacity: 0.15,
                  filter: "blur(2px)",
                }}
              />
            );
          })}

          <AbsoluteFill style={{ justifyContent: "flex-start", alignItems: "flex-end", padding: "15% 8%" }}>
            <div style={{ transform: `translateX(${s2X}px)`, filter: `blur(${s2Blur}px)`, display: "flex", flexDirection: "column", alignItems: "flex-end" }}>
              <h2
                style={{
                  fontSize: width * 0.1,
                  margin: 0,
                  textTransform: "uppercase",
                  fontStyle: "italic",
                  letterSpacing: "0.05em",
                }}
              >
                {syncText}
              </h2>
              <div
                style={{
                  height: 8,
                  backgroundColor: accentColor,
                  width: "100%",
                  marginTop: 8,
                  transform: `scaleX(${s2LineScale})`,
                  transformOrigin: "right center",
                }}
              />
            </div>
          </AbsoluteFill>

          {/* Staggered Sub-Lines to keep visual momentum during hold */}
          <AbsoluteFill style={{ justifyContent: "flex-end", alignItems: "flex-start", padding: "20% 8%" }}>
            <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
              {syncSubLines.map((line, i) => {
                const lineSpring = spring({
                  frame: s2LocalFrame - 25 - (i * 12),
                  fps,
                  config: { damping: 14, stiffness: 120 },
                });
                const lineX = interpolate(lineSpring, [0, 1], [-150, 0]);
                return (
                  <div
                    key={i}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      opacity: lineSpring,
                      transform: `translateX(${lineX}px)`,
                    }}
                  >
                    <div
                      style={{
                        width: 12,
                        height: 12,
                        backgroundColor: accentColor,
                        marginRight: 15,
                        transform: "rotate(45deg)",
                      }}
                    />
                    <span
                      style={{
                        fontSize: width * 0.055,
                        textTransform: "uppercase",
                        letterSpacing: "0.05em",
                        color: textColor,
                        textShadow: "2px 2px 0px rgba(0,0,0,0.5)",
                      }}
                    >
                      {line}
                    </span>
                  </div>
                );
              })}
            </div>
          </AbsoluteFill>
        </AbsoluteFill>
      </Sequence>

      {/* --- SCENE 3: PERFORMANCE STACK --- */}
      <Sequence from={p40} durationInFrames={p65 - p40}>
        <AbsoluteFill style={{ opacity: s3Opacity }}>
          {/* Micro Flash on change */}
          <AbsoluteFill style={{ backgroundColor: "#FFFFFF", opacity: s3FlashOpacity }} />
          
          <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
            {s3LocalFrame >= 0 && s3LocalFrame < s3TotalDuration && (
              <h1
                style={{
                  fontSize: width * 0.2,
                  margin: 0,
                  textTransform: "uppercase",
                  transform: `translateY(${s3WordY}px) skewX(-5deg)`,
                  opacity: s3WordOpacity,
                  color: currentWordIndex === stackWords.length - 1 ? accentColor : textColor,
                  textShadow: "0 10px 20px rgba(0,0,0,0.5)",
                }}
              >
                {stackWords[currentWordIndex]}
              </h1>
            )}
          </AbsoluteFill>
        </AbsoluteFill>
      </Sequence>

      {/* --- SCENE 4: ADVANTAGE FRAME --- */}
      <Sequence from={p60} durationInFrames={p85 - p60}>
        <AbsoluteFill style={{ opacity: s4Opacity }}>
          {/* Localized dark contrast block */}
          <AbsoluteFill
            style={{
              top: height * 0.6,
              background: `linear-gradient(0deg, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0) 100%)`,
              opacity: s4BgOpacity,
            }}
          />
          <AbsoluteFill style={{ justifyContent: "flex-end", paddingBottom: "20%", paddingLeft: "8%" }}>
            <div style={{ overflow: "hidden", paddingBottom: 10 }}>
              <h2
                style={{
                  fontSize: width * 0.08,
                  margin: 0,
                  color: "#CCCCCC",
                  textTransform: "uppercase",
                  transform: `translateY(${s4Y1}px)`,
                }}
              >
                {advantageLine1}
              </h2>
            </div>
            <div style={{ overflow: "hidden" }}>
              <h1
                style={{
                  fontSize: width * 0.15,
                  margin: 0,
                  lineHeight: 1,
                  textTransform: "uppercase",
                  transform: `translateY(${s4Y2}px)`,
                }}
              >
                {advantageLine2}
              </h1>
            </div>
            <div
              style={{
                height: 4,
                backgroundColor: accentColor,
                width: width * 0.8,
                marginTop: 20,
                transform: `scaleX(${s4LineScale})`,
                transformOrigin: "left center",
                boxShadow: `0 0 10px ${accentColor}`,
              }}
            />
          </AbsoluteFill>
        </AbsoluteFill>
      </Sequence>

      {/* --- SCENE 5: FINAL HIT WITH CTA HOLD --- */}
      <Sequence from={p80} durationInFrames={durationInFrames - p80}>
        <AbsoluteFill
          style={{
            justifyContent: "center",
            alignItems: "center",
            transform: `scale(${s5ScaleIn})`,
            opacity: s5Opacity,
          }}
        >
          {logoImage && (
            <Img
              src={logoImage}
              style={{
                maxWidth: width * 0.5,
                maxHeight: height * 0.25,
                objectFit: "contain",
                marginBottom: 30,
                filter: `drop-shadow(0px 0px ${s5Glow}px ${accentColor})`,
              }}
            />
          )}
          <h2
            style={{
              fontSize: width * 0.1,
              margin: 0,
              textTransform: "uppercase",
              letterSpacing: "0.02em",
              textShadow: "0 10px 20px rgba(0,0,0,0.8)",
              marginBottom: 50,
            }}
          >
            {finalLine2}
          </h2>

          {/* CTA Button */}
          {ctaText && (
            <div
              style={{
                backgroundColor: accentColor,
                color: "#000000",
                padding: "20px 60px",
                borderRadius: "50px",
                fontWeight: "bold",
                fontSize: width * 0.06,
                textTransform: "uppercase",
                letterSpacing: "0.05em",
                boxShadow: `0 10px 30px rgba(0,0,0,0.5)`,
                transform: `scale(${s5CtaScale})`,
              }}
            >
              {ctaText}
            </div>
          )}
        </AbsoluteFill>
      </Sequence>
    </AbsoluteFill>
  );
};

export default KineticOverlay;